from django.utils import timezone


def crear_historico_inicial(apps, schema_editor):
    """Crea un historico inicial para cada costo existente.

    Asi el primer cambio de precio de costo tiene una version anterior con la
    que comparar y el detalle de actividad puede mostrar el diff.
    """
    ProductoXProveedor = apps.get_model('app', 'ProductoXProveedor')
    HistoricalProductoXProveedor = apps.get_model(
        'app', 'HistoricalProductoXProveedor'
    )
    existentes = HistoricalProductoXProveedor.objects.values_list(
        'id', flat=True
    )
    ya_historizados = set(existentes)
    ahora = timezone.now()
    nuevos = []
    for costo in ProductoXProveedor.objects.all():
        if costo.id in ya_historizados:
            continue
        nuevos.append(
            HistoricalProductoXProveedor(
                id=costo.id,
                producto_id=costo.producto_id,
                proveedor_id=costo.proveedor_id,
                codigo_producto_proveedor=costo.codigo_producto_proveedor,
                precio_lista=costo.precio_lista,
                estado=costo.estado,
                history_date=ahora,
                history_type='+',
                history_user=None,
                history_change_reason='Historico inicial',
            )
        )
    if nuevos:
        HistoricalProductoXProveedor.objects.bulk_create(nuevos)


